"""
        Create an octave-repeating scale from a tonic note
        and a pattern of intervals

        Args:
            tonic: root note (midi note number)
            pattern: pattern of intervals (list of numbers representing
            intervals in semitones)
            octave: span of scale (in octaves)

        Returns:
            list of midi notes in the scale
    """
def create_scale(tonic: Any, pattern: Any, octave: Any = 1) -> object {
    assert (sum(pattern) == 12);
    scale = [tonic];
    note = tonic;
    for o in range(octave) {
        for i in pattern {
            note += i;
            if (note <= 127) {
                scale.append(note);
            }
        }
    }
    return scale;
}

"""
    Function to return text as bold

    :param text: str to bold
    :type text: str
    :return: str in bold
    """
def bold(text: Any) -> object {
    return ('\x1b[1;30m' + text + '\x1b[0m') if text else ('\x1b[1;30m' + '\x1b[0m');
}

"""Convert a zerocoded bytestring into a bytestring"""
def decode(bytedata: Any) -> object {
    i = 0;
    l = len(bytedata);
    while (i < l) {
        if (bytedata[i] == 0) {
            c = bytedata[(i + 1)] - 1;
            bytedata = bytedata[:(i + 1)] + (b'\x00' * c) + bytedata[(i + 2):];
            i = i + c;
            l = (l + c) - 1;
        }
        i = i + 1;
    }
    return bytedata;
}

"""Returns a list of HTTP headers given the MIME type and the length of the
    content, in bytes (in integer or sting format)."""
def headers(mime: Any, length: Any) -> object {
    return [('Content-Type', mime), ('Content-Length', str(length))];
}

