"""
    Merge dicts by key
    :param this:
    :param other:
    :param cb:
    :return:
    """
def merge_dict(this: Any, other: Any, cb: Any) -> object {
    result = {};
    result.update(this);
    result.update(other);
    for key in (this.keys() & other) {
        ret = cb(this[key], other[key]);
        result[key] = ret;
    }
    return result;
}

"""Returns concatenated product of n with 1-m (until digits > 8)"""
def multiply_by_1_m(n: Any) -> object {
    conc_product = "";
    i = 1;
    while (len(conc_product) < 9) {
        conc_product += str((n * i));
        i += 1;
    }
    return int(conc_product);
}

