"""Deletes all the spaces of a string

    Parameters:
    -----------
    s : str

    Returns
    -----------
        The corresponding string
    """
def delete_spaces(s: Any) -> object {
    s = ''.join(
        i
        for i in s
        if (i != ' ')
    );
    return s;
}
